extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var tester: Object = instantiate_script("res://story/test_history.gd")
	if not check("instance", tester != null, "Lo script story/test_history.gd deve potersi istanziare"):
		return

	if not check("method", has_function(tester, "test_history_recording"), "La classe deve contenere la funzione test_history_recording"):
		return

	var list: Array[Dictionary] = []
	var res_empty = call_if_exists(tester, "test_history_recording", [list, {}], true)
	check("empty_data", res_empty == false, "Se line_data è vuoto la funzione deve restituire false")

	var valid_entry: Dictionary = {"speaker": "Elena", "text": "Ciao!"}
	var res_valid = call_if_exists(tester, "test_history_recording", [list, valid_entry], false)
	check("valid_entry", res_valid == true and list.size() == 1, "Con dati validi aggiunge l'elemento e restituisce true")

	var invalid_entry: Dictionary = {"speaker": "Marco"}
	var res_invalid = call_if_exists(tester, "test_history_recording", [list, invalid_entry], true)
	check("missing_text", res_invalid == false, "Se manca la chiave text la funzione deve restituire false")

