	}
	var res_valid = call_if_exists(tester, "test_jump_command", [valid_cmd], false)
	check("valid_cmd", res_valid == true, "Un comando jump_chapter ben formato deve restituire true")

	var empty_cmd: Dictionary = {}
	var res_empty = call_if_exists(tester, "test_jump_command", [empty_cmd], true)
	check("empty_cmd", res_empty == false, "Un comando vuoto deve restituire false")

	var wrong_type: Dictionary = {
		"type": "jump",
		"target_file": "res://story/chapters/chapter_02.json",
		"target_label": "sala_centrale"
	}
	var res_wrong_type = call_if_exists(tester, "test_jump_command", [wrong_type], true)
	check("wrong_type", res_wrong_type == false, "Un comando con type non pari a jump_chapter deve restituire false")

	var non_json: Dictionary = {
		"type": "jump_chapter",
		"target_file": "res://story/chapters/chapter_02.tres",
		"target_label": "sala_centrale"
	}
	var res_non_json = call_if_exists(tester, "test_jump_command", [non_json], true)
	check("non_json", res_non_json == false, "Se target_file non termina con .json la funzione deve restituire false")

	var empty_label: Dictionary = {
		"type": "jump_chapter",
		"target_file": "res://story/chapters/chapter_02.json",
		"target_label": ""
	}
	var res_empty_label = call_if_exists(tester, "test_jump_command", [empty_label], true)
	check("empty_label", res_empty_label == false, "Se target_label è vuota la funzione deve restituire false")

