class_name TestChapterJump
extends RefCounted


func test_jump_command(command: Dictionary) -> bool:
	if command.is_empty():
		return false

	if String(command.get("type", "")) != "jump_chapter":
		return false

	if not command.has("target_file") or not command.has("target_label"):
		return false

	var file_path: String = String(command.get("target_file", ""))
	var label_name: String = String(command.get("target_label", ""))

	if not file_path.ends_with(".json"):
		return false

	if label_name.is_empty():
		return false

	return true

